import type { Question } from '../questions';

const source = { kind: 'original' as const, reference: "Original GPAT practice questions, second full mock, written to the published GPAT subject list in the same proportions as the first mock: Pharmaceutics, Pharmaceutical Chemistry, Pharmacology, Pharmaceutical Analysis, Pharmacognosy, Biochemistry and Human Physiology, Pharmaceutical Microbiology and Biotechnology, and Pharmaceutical Jurisprudence and Pharmacy Practice. Every answer is settled undergraduate pharmacy textbook content, a definition, or a calculation that can be checked from the question itself. Questions turning on current prescribing choice, current price control or any figure that changes between cycles are excluded.", url: 'https://natboard.edu.in/', checkedOn: '10 September 2026' };

export const GPAT_2026_PHARMACY_FULL_MOCK_2: Question[] = [
  { id: 'gpat-2026-pharmacy-02-001', section: 'Pharmacy', topic: 'Pharmaceutics: rheology', difficulty: 'easy', question: 'Which of the following is the CGS unit of dynamic viscosity?', options: ['Poise', 'Pascal', 'Newton', 'Stokes'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The CGS unit of dynamic viscosity is the poise, equal to 0.1 pascal second. The stokes is the unit of kinematic viscosity, while the pascal and the newton measure pressure and force.', source },
  { id: 'gpat-2026-pharmacy-02-002', section: 'Pharmacy', topic: 'Pharmaceutics: HLB system', difficulty: 'medium', question: 'An emulsifier intended to produce an oil in water emulsion generally has an HLB value in the range', options: ['1 to 3', '8 to 18', '3 to 6', 'below 1'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Higher HLB values indicate a more hydrophilic surfactant, which favours an oil in water emulsion. Values of about 3 to 6 favour water in oil emulsions and values of 1 to 3 suit antifoaming agents.', source },
  { id: 'gpat-2026-pharmacy-02-003', section: 'Pharmacy', topic: 'Pharmaceutics: Stokes\' law', difficulty: 'medium', question: 'According to Stokes\' law, the rate of sedimentation of a particle in a suspension is proportional to', options: ['the particle radius', 'the cube of the particle radius', 'the square of the particle radius', 'the reciprocal of the particle radius'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Stokes\' law gives the sedimentation velocity as proportional to the square of the radius, to the density difference and to the reciprocal of the viscosity of the medium. Reducing particle size therefore slows settling sharply.', source },
  { id: 'gpat-2026-pharmacy-02-004', section: 'Pharmacy', topic: 'Pharmaceutics: emulsion instability', difficulty: 'medium', question: 'Creaming of an emulsion is best described as', options: ['irreversible fusion of droplets into a continuous phase', 'conversion of an oil in water emulsion into water in oil', 'chemical degradation of the emulsifying agent', 'a reversible upward or downward movement of dispersed droplets'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Creaming is a concentration gradient produced by droplets rising or settling and is reversed by shaking. Coalescence, in which droplets fuse, is irreversible, and phase inversion is a separate phenomenon.', source },
  { id: 'gpat-2026-pharmacy-02-005', section: 'Pharmacy', topic: 'Pharmaceutics: thixotropy', difficulty: 'medium', question: 'A semisolid whose apparent viscosity falls with time under a constant rate of shear and recovers on standing is described as', options: ['thixotropic', 'dilatant', 'Newtonian', 'plastic'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Thixotropy is an isothermal, reversible loss of consistency with time under shear. Dilatant systems thicken as shear increases, and a Newtonian fluid has a viscosity independent of both shear rate and time.', source },
  { id: 'gpat-2026-pharmacy-02-006', section: 'Pharmacy', topic: 'Pharmaceutics: Newtonian flow', difficulty: 'easy', question: 'A Newtonian liquid is one in which', options: ['viscosity falls as shear rate rises', 'viscosity is independent of the rate of shear', 'viscosity rises as shear rate rises', 'flow begins only above a yield value'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'For a Newtonian liquid the shear stress is directly proportional to the shear rate, so the viscosity is a constant. Water, glycerin and simple syrup behave in this way.', source },
  { id: 'gpat-2026-pharmacy-02-007', section: 'Pharmacy', topic: 'Pharmaceutics: tablet excipients', difficulty: 'medium', question: 'Croscarmellose sodium is included in a tablet formulation primarily as', options: ['a lubricant', 'a binder', 'a superdisintegrant', 'a glidant'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Croscarmellose sodium swells rapidly on contact with water and breaks the tablet apart. Magnesium stearate is a lubricant, povidone a common binder and colloidal silicon dioxide a glidant.', source },
  { id: 'gpat-2026-pharmacy-02-008', section: 'Pharmacy', topic: 'Pharmaceutics: tablet lubricants', difficulty: 'easy', question: 'Magnesium stearate is added to a tablet granulation chiefly to', options: ['improve the flow of granules into the die', 'bind the powder particles together', 'speed up disintegration in the stomach', 'reduce friction between the tablet and the die wall'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Magnesium stearate is a boundary lubricant that eases ejection of the tablet from the die. Excess amounts are hydrophobic and can retard both disintegration and dissolution.', source },
  { id: 'gpat-2026-pharmacy-02-009', section: 'Pharmacy', topic: 'Pharmaceutics: tablet defects', difficulty: 'medium', question: 'Capping in tablet compression refers to', options: ['separation of the upper or lower segment of the tablet from the main body', 'adhesion of tablet material to the punch faces', 'splitting of the tablet into horizontal layers on ejection', 'an uneven colour distribution across the tablet surface'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Capping is the partial or complete separation of the top or bottom cap of a tablet. Lamination is separation into layers, picking and sticking describe adhesion to the punch, and mottling describes uneven colour.', source },
  { id: 'gpat-2026-pharmacy-02-010', section: 'Pharmacy', topic: 'Pharmaceutics: capsules', difficulty: 'easy', question: 'The shell of a hard capsule of the conventional type is made principally of', options: ['starch', 'gelatin', 'cellulose acetate', 'polyvinyl alcohol'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Hard capsule shells are traditionally made from gelatin with water and colourants. Hypromellose shells are the common vegetarian alternative, but starch and cellulose acetate are not used for the shell itself.', source },
  { id: 'gpat-2026-pharmacy-02-011', section: 'Pharmacy', topic: 'Pharmaceutics: capsules', difficulty: 'medium', question: 'Among hard capsule sizes 0, 1, 2 and 3, which has the largest fill volume?', options: ['Size 1', 'Size 2', 'Size 0', 'Size 3'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Hard capsule numbering runs in the opposite direction to volume: the smaller the number, the larger the capsule. Size 0 therefore holds more than sizes 1, 2 and 3.', source },
  { id: 'gpat-2026-pharmacy-02-012', section: 'Pharmacy', topic: 'Pharmaceutics: coating', difficulty: 'easy', question: 'An enteric coating is applied to a tablet so that it will', options: ['dissolve immediately in the mouth', 'release the drug at a constant rate over 12 hours', 'mask the taste without affecting the release site', 'resist gastric fluid and dissolve in the intestine'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Enteric polymers such as cellulose acetate phthalate are insoluble at gastric pH and dissolve at the higher pH of the small intestine, protecting acid labile drugs and sparing the gastric mucosa.', source },
  { id: 'gpat-2026-pharmacy-02-013', section: 'Pharmacy', topic: 'Pharmaceutics: zero-order release', difficulty: 'medium', question: 'A dosage form showing zero order release delivers the drug', options: ['at a constant rate independent of the amount remaining', 'at a rate proportional to the amount remaining', 'in a single rapid pulse', 'at a rate proportional to the square root of time'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Zero order kinetics gives a straight line when the amount released is plotted against time. First order release is proportional to the amount remaining, and the Higuchi model gives a square root of time dependence.', source },
  { id: 'gpat-2026-pharmacy-02-014', section: 'Pharmacy', topic: 'Pharmaceutics: dissolution testing', difficulty: 'medium', question: 'In the compendial dissolution apparatus 2, the stirring element is', options: ['a rotating basket', 'a paddle', 'a reciprocating cylinder', 'a flow through cell'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Apparatus 2 uses a paddle. Apparatus 1 uses a rotating basket, apparatus 3 a reciprocating cylinder and apparatus 4 a flow through cell.', source },
  { id: 'gpat-2026-pharmacy-02-015', section: 'Pharmacy', topic: 'Pharmaceutics: micromeritics', difficulty: 'easy', question: 'The angle of repose of a powder is used as a measure of', options: ['particle density', 'moisture content', 'flow property', 'compressibility of the tablet'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The angle of repose is the steepest angle of the free surface of a heap of powder. Lower angles, roughly below 30 degrees, indicate free flowing material.', source },
  { id: 'gpat-2026-pharmacy-02-016', section: 'Pharmacy', topic: 'Pharmaceutics: Carr\'s index', difficulty: 'medium', question: 'A Carr\'s compressibility index between 5 and 15 per cent indicates', options: ['poor flow', 'very poor flow', 'no useful conclusion about flow', 'excellent flow'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Carr\'s index compares tapped and bulk density. Values of 5 to 15 per cent indicate excellent flow, while values above about 25 per cent indicate poor flow.', source },
  { id: 'gpat-2026-pharmacy-02-017', section: 'Pharmacy', topic: 'Pharmaceutics: sterilisation', difficulty: 'easy', question: 'The conventional cycle for moist heat sterilisation in an autoclave is', options: ['121 degrees Celsius for 15 minutes at 15 psi', '160 degrees Celsius for 15 minutes', '100 degrees Celsius for 60 minutes', '134 degrees Celsius for 60 minutes'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Saturated steam at 121 degrees Celsius and about 15 pounds per square inch above atmospheric pressure for 15 minutes is the reference moist heat cycle.', source },
  { id: 'gpat-2026-pharmacy-02-018', section: 'Pharmacy', topic: 'Pharmaceutics: dry heat sterilisation', difficulty: 'medium', question: 'Dry heat sterilisation of glass apparatus in a hot air oven is usually carried out at', options: ['121 degrees Celsius for 15 minutes', '160 degrees Celsius for 2 hours', '100 degrees Celsius for 30 minutes', '180 degrees Celsius for 5 minutes'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Dry heat transfers energy far less efficiently than steam, so higher temperatures and longer times are needed. The usual cycles are 160 degrees for 2 hours or 170 degrees for 1 hour.', source },
  { id: 'gpat-2026-pharmacy-02-019', section: 'Pharmacy', topic: 'Pharmaceutics: parenteral products', difficulty: 'hard', question: 'Depyrogenation of glass ampoules is most reliably achieved by', options: ['autoclaving at 121 degrees Celsius', 'filtration through a 0.22 micrometre membrane', 'dry heat at about 250 degrees Celsius', 'washing with sterile water for injection'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Endotoxin is far more heat stable than the organism that produced it. Autoclaving kills bacteria without destroying pyrogen, whereas dry heat at 250 degrees for 30 minutes or more destroys it.', source },
  { id: 'gpat-2026-pharmacy-02-020', section: 'Pharmacy', topic: 'Pharmaceutics: pyrogens', difficulty: 'medium', question: 'Pyrogens of pharmaceutical concern are chiefly', options: ['exotoxins secreted by Gram positive bacteria', 'fungal spores carried in the air', 'residues of the preservative used in the formulation', 'lipopolysaccharides from the cell wall of Gram negative bacteria'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The clinically important pyrogen is bacterial endotoxin, a lipopolysaccharide from the outer membrane of Gram negative organisms, which raises body temperature when injected.', source },
  { id: 'gpat-2026-pharmacy-02-021', section: 'Pharmacy', topic: 'Pharmaceutics: endotoxin testing', difficulty: 'medium', question: 'The Limulus amoebocyte lysate test is used to detect', options: ['bacterial endotoxin', 'viable bacterial contamination', 'particulate matter in an injection', 'residual moisture in a lyophilised cake'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The lysate from horseshoe crab amoebocytes gels in the presence of endotoxin, providing a sensitive in vitro replacement for the rabbit pyrogen test.', source },
  { id: 'gpat-2026-pharmacy-02-022', section: 'Pharmacy', topic: 'Pharmaceutics: tonicity', difficulty: 'easy', question: 'A solution that exerts the same osmotic pressure as blood plasma is described as', options: ['hypertonic', 'isotonic', 'hypotonic', 'isohydric'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'An isotonic solution causes no net movement of water across the red cell membrane. Sodium chloride 0.9 per cent w/v and dextrose 5 per cent w/v are the standard examples.', source },
  { id: 'gpat-2026-pharmacy-02-023', section: 'Pharmacy', topic: 'Pharmaceutics: tonicity', difficulty: 'hard', question: 'The sodium chloride equivalent of a drug is used to', options: ['measure the buffer capacity of the vehicle', 'estimate the partition coefficient of the drug', 'calculate the amount of sodium chloride needed to make a solution isotonic', 'predict the shelf life of the preparation'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The sodium chloride equivalent is the weight of sodium chloride producing the same osmotic effect as one gram of the drug, and it lets the tonicity adjustment be calculated directly.', source },
  { id: 'gpat-2026-pharmacy-02-024', section: 'Pharmacy', topic: 'Pharmaceutics: buffers', difficulty: 'medium', question: 'The buffer capacity of a weak acid buffer is at its maximum when', options: ['the pH is two units above the pKa', 'the pH is two units below the pKa', 'the acid is completely ionised', 'the pH equals the pKa of the acid'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Capacity peaks where the concentrations of the acid and its conjugate base are equal, which by the Henderson Hasselbalch equation is where the pH equals the pKa.', source },
  { id: 'gpat-2026-pharmacy-02-025', section: 'Pharmacy', topic: 'Pharmaceutics: preservatives', difficulty: 'medium', question: 'Which preservative is most commonly used in multi dose eye drop formulations?', options: ['Benzalkonium chloride', 'Sodium metabisulphite', 'Disodium edetate', 'Butylated hydroxytoluene'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Benzalkonium chloride is the usual antimicrobial preservative for multi dose ophthalmic products. Metabisulphite is an antioxidant, edetate a chelating agent and butylated hydroxytoluene an antioxidant for oily vehicles.', source },
  { id: 'gpat-2026-pharmacy-02-026', section: 'Pharmacy', topic: 'Pharmaceutics: lyophilisation', difficulty: 'medium', question: 'The primary drying stage of lyophilisation removes water by', options: ['evaporation from the liquid state at atmospheric pressure', 'sublimation of ice under reduced pressure', 'adsorption onto a chemical desiccant', 'centrifugation of the frozen mass'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'In primary drying the product is held below its eutectic temperature and the chamber pressure is lowered so that ice passes directly to vapour. Secondary drying then removes the remaining bound water by desorption.', source },
  { id: 'gpat-2026-pharmacy-02-027', section: 'Pharmacy', topic: 'Pharmaceutics: aerosols', difficulty: 'medium', question: 'Chlorofluorocarbon propellants in metered dose inhalers have largely been replaced by', options: ['compressed nitrogen', 'carbon dioxide', 'hydrofluoroalkanes', 'dimethyl ether'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Hydrofluoroalkanes such as HFA 134a and HFA 227 contain no chlorine and do not deplete stratospheric ozone, so they replaced the chlorofluorocarbons under the Montreal Protocol.', source },
  { id: 'gpat-2026-pharmacy-02-028', section: 'Pharmacy', topic: 'Pharmaceutics: ointment bases', difficulty: 'easy', question: 'Which of the following is an oleaginous ointment base?', options: ['Polyethylene glycol ointment', 'Hydrophilic ointment', 'Bentonite magma', 'White petrolatum'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'White petrolatum is a hydrocarbon base that is occlusive and anhydrous. Polyethylene glycol ointment is water soluble and hydrophilic ointment is an oil in water base.', source },
  { id: 'gpat-2026-pharmacy-02-029', section: 'Pharmacy', topic: 'Pharmaceutics: suppositories', difficulty: 'medium', question: 'Which suppository base is water soluble?', options: ['Polyethylene glycol', 'Theobroma oil', 'Hydrogenated vegetable oil', 'Hard paraffin'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Polyethylene glycol bases dissolve in the body fluids rather than melting. Theobroma oil and hydrogenated vegetable oils are fatty bases that release the drug by melting at body temperature.', source },
  { id: 'gpat-2026-pharmacy-02-030', section: 'Pharmacy', topic: 'Pharmaceutics: compounding', difficulty: 'easy', question: 'Geometric dilution is used when', options: ['two liquids of different viscosity must be emulsified', 'a small quantity of a potent drug must be mixed uniformly with a much larger quantity of diluent', 'a powder must be granulated before compression', 'a solution must be rendered isotonic with blood'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'In geometric dilution the potent powder is first mixed with an approximately equal volume of diluent, and the mixture is then doubled repeatedly until all the diluent is incorporated, which prevents an uneven distribution.', source },
  { id: 'gpat-2026-pharmacy-02-031', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: barbiturates', difficulty: 'medium', question: 'Barbiturates are derivatives of', options: ['benzodiazepine', 'phenothiazine', 'malonylurea', 'indole'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Barbituric acid is the condensation product of malonic acid and urea, and the hypnotic barbiturates are substituted at position 5 of that ring.', source },
  { id: 'gpat-2026-pharmacy-02-032', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: analgesics', difficulty: 'easy', question: 'Aspirin is chemically', options: ['salicylamide', 'methyl salicylate', 'p-aminophenol', 'acetylsalicylic acid'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Aspirin is the acetyl ester of salicylic acid at the phenolic hydroxyl group, which is why it acetylates cyclooxygenase irreversibly.', source },
  { id: 'gpat-2026-pharmacy-02-033', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: analgesics', difficulty: 'easy', question: 'Paracetamol is chemically', options: ['N-acetyl-p-aminophenol', 'N-acetyl-o-aminophenol', 'p-aminobenzoic acid', 'acetanilide'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Paracetamol, also called acetaminophen, is the para substituted acetamide of aminophenol. Acetanilide is the older, more toxic analogue lacking the phenolic hydroxyl.', source },
  { id: 'gpat-2026-pharmacy-02-034', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: antibacterials', difficulty: 'medium', question: 'Sulphonamide antibacterials act as structural analogues of', options: ['folic acid', 'para-aminobenzoic acid', 'dihydrofolate reductase', 'thymidine'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Sulphonamides compete with para-aminobenzoic acid for dihydropteroate synthase, blocking bacterial folate synthesis. Human cells take up preformed folate and are therefore spared.', source },
  { id: 'gpat-2026-pharmacy-02-035', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: heterocycles', difficulty: 'easy', question: 'Pyrrole is', options: ['a six membered aromatic ring containing one nitrogen atom', 'a five membered ring containing two nitrogen atoms', 'a five membered aromatic ring containing one nitrogen atom', 'a six membered ring containing two nitrogen atoms'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Pyrrole has four carbon atoms and one nitrogen in a five membered aromatic ring. Pyridine is the six membered analogue and imidazole the five membered ring with two nitrogens.', source },
  { id: 'gpat-2026-pharmacy-02-036', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: heterocycles', difficulty: 'easy', question: 'Pyridine is best described as', options: ['a five membered aromatic ring with one nitrogen atom', 'a six membered saturated ring with one nitrogen atom', 'a bicyclic ring system with two nitrogen atoms', 'a six membered aromatic ring with one nitrogen atom'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Pyridine is the aza analogue of benzene, aromatic and basic because the nitrogen lone pair lies in the ring plane and is not part of the aromatic sextet. The saturated analogue is piperidine.', source },
  { id: 'gpat-2026-pharmacy-02-037', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: heterocycles', difficulty: 'medium', question: 'Imidazole contains', options: ['two nitrogen atoms in a five membered ring', 'one nitrogen atom in a five membered ring', 'two nitrogen atoms in a six membered ring', 'three nitrogen atoms in a five membered ring'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Imidazole has nitrogens at positions 1 and 3 of a five membered aromatic ring. It appears in histamine, histidine and the antifungal azoles.', source },
  { id: 'gpat-2026-pharmacy-02-038', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: antibiotics', difficulty: 'medium', question: 'The four membered ring fused to a thiazolidine ring in penicillins is', options: ['a lactone', 'a beta-lactam', 'an anhydride', 'an imide'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The beta-lactam is a strained cyclic amide, and its acylation of the bacterial transpeptidase is what gives penicillins their action. Its strain also makes it vulnerable to beta-lactamase.', source },
  { id: 'gpat-2026-pharmacy-02-039', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: heterocycles', difficulty: 'medium', question: 'The indole nucleus consists of', options: ['a benzene ring fused to a pyridine ring', 'two fused pyrrole rings', 'a benzene ring fused to a pyrrole ring', 'a benzene ring fused to a furan ring'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Indole is a bicyclic system of benzene fused to pyrrole. Quinoline is benzene fused to pyridine and benzofuran is benzene fused to furan.', source },
  { id: 'gpat-2026-pharmacy-02-040', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: vitamins', difficulty: 'medium', question: 'Which vitamin contains a corrin ring system with a central cobalt atom?', options: ['Vitamin B6', 'Vitamin K', 'Vitamin A', 'Vitamin B12'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Cyanocobalamin is built around a corrin macrocycle coordinating cobalt, which is why the vitamin is also called cobalamin.', source },
  { id: 'gpat-2026-pharmacy-02-041', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: physicochemical properties', difficulty: 'easy', question: 'The partition coefficient log P of a compound is a measure of its', options: ['lipophilicity', 'acidity', 'molar mass', 'optical rotation'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Log P is the logarithm of the ratio of concentrations of the un-ionised compound between octanol and water, and it correlates with membrane permeability.', source },
  { id: 'gpat-2026-pharmacy-02-042', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: QSAR', difficulty: 'hard', question: 'In the Hansch approach to quantitative structure activity relationships, the Hammett sigma constant describes', options: ['the steric bulk of a substituent', 'the electronic effect of a substituent', 'the lipophilicity of a substituent', 'the molar refractivity of the whole molecule'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Sigma quantifies electron withdrawal or donation. Pi describes the lipophilic contribution of a substituent and Taft\'s Es the steric contribution.', source },
  { id: 'gpat-2026-pharmacy-02-043', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: QSAR', difficulty: 'hard', question: 'The Taft steric parameter Es is used in a QSAR equation to describe', options: ['the electronic effect of a substituent', 'the hydrogen bonding capacity of a substituent', 'the steric bulk of a substituent', 'the aqueous solubility of the parent drug'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Es was derived from the rates of acid catalysed ester hydrolysis and isolates the steric contribution of a substituent from its electronic contribution.', source },
  { id: 'gpat-2026-pharmacy-02-044', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: prodrugs', difficulty: 'easy', question: 'A prodrug is best defined as', options: ['a drug that acts only on the prostate', 'the first drug given in a treatment course', 'a metabolite that is more toxic than the parent drug', 'an inactive derivative that is converted in the body to the active drug'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'A prodrug is designed to improve absorption, stability, taste or targeting, and releases the active molecule by chemical or enzymatic conversion after administration.', source },
  { id: 'gpat-2026-pharmacy-02-045', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: prodrugs', difficulty: 'medium', question: 'Enalapril is a prodrug that is hydrolysed in the body to', options: ['enalaprilat', 'captopril', 'lisinopril', 'ramiprilat'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The ethyl ester of enalapril improves oral absorption and is cleaved by hepatic esterases to enalaprilat, the active angiotensin converting enzyme inhibitor.', source },
  { id: 'gpat-2026-pharmacy-02-046', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: metabolism', difficulty: 'medium', question: 'Which of the following is a phase II conjugation reaction?', options: ['Aromatic hydroxylation', 'Glucuronidation', 'Oxidative deamination', 'Ester hydrolysis'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Phase II reactions attach an endogenous polar group. Glucuronidation, sulphation, acetylation and glutathione conjugation are the main examples; hydroxylation, deamination and hydrolysis are phase I.', source },
  { id: 'gpat-2026-pharmacy-02-047', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: metabolism', difficulty: 'easy', question: 'Hydroxylation of a drug by a cytochrome P450 enzyme is an example of', options: ['phase II metabolism', 'phase III transport', 'phase I metabolism', 'enterohepatic recirculation'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Phase I reactions introduce or unmask a functional group by oxidation, reduction or hydrolysis, often preparing the molecule for a phase II conjugation.', source },
  { id: 'gpat-2026-pharmacy-02-048', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: bioisosterism', difficulty: 'hard', question: 'Which group is a classical bioisostere of a carboxylic acid used to improve metabolic stability?', options: ['Primary amine', 'Methyl ether', 'Nitro group', 'Tetrazole'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'A tetrazole ring has a comparable pKa and a similar anionic shape to a carboxylate but resists glucuronidation, which is why losartan and several other drugs use it.', source },
  { id: 'gpat-2026-pharmacy-02-049', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: stereochemistry', difficulty: 'medium', question: 'In a pair of enantiomers of a drug, the eutomer is', options: ['the enantiomer with the greater pharmacological activity', 'the enantiomer with the lower activity', 'the racemic mixture of the two', 'the metabolite common to both'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The more active enantiomer is the eutomer and the less active one the distomer. Their activity ratio is called the eudismic ratio.', source },
  { id: 'gpat-2026-pharmacy-02-050', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: drug design', difficulty: 'medium', question: 'Levodopa rather than dopamine is given in Parkinson\'s disease because levodopa', options: ['is more potent at dopamine receptors', 'crosses the blood brain barrier', 'has a longer plasma half life', 'is not metabolised in the periphery'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Dopamine is too polar to cross the blood brain barrier, whereas levodopa is carried across by the large neutral amino acid transporter and is then decarboxylated to dopamine in the brain.', source },
  { id: 'gpat-2026-pharmacy-02-051', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: functional groups', difficulty: 'easy', question: 'A beta-lactam ring is', options: ['a cyclic ester contained in a five membered ring', 'a cyclic ether contained in a six membered ring', 'a cyclic amide contained in a four membered ring', 'an open chain amide'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The beta-lactam is an amide whose nitrogen and carbonyl carbon lie in a strained four membered ring, and that strain drives its acylating reactivity.', source },
  { id: 'gpat-2026-pharmacy-02-052', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: antibacterials', difficulty: 'hard', question: 'The fluoroquinolone antibacterials are built on which nucleus?', options: ['Beta-lactam fused to dihydrothiazine', 'Tetracyclic naphthacene carboxamide', 'Macrocyclic lactone', '4-oxo-quinoline-3-carboxylic acid'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The quinolones carry a carboxylic acid at position 3 and a ketone at position 4 on a quinoline ring, with fluorine usually at position 6. The other options describe cephalosporins, tetracyclines and macrolides.', source },
  { id: 'gpat-2026-pharmacy-02-053', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: hormones', difficulty: 'easy', question: 'Which element is an essential constituent of the thyroid hormones?', options: ['Iodine', 'Iron', 'Zinc', 'Selenium'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Thyroxine carries four iodine atoms and triiodothyronine three. Iodine deficiency therefore limits thyroid hormone synthesis.', source },
  { id: 'gpat-2026-pharmacy-02-054', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: steroids', difficulty: 'medium', question: 'The steroid nucleus is chemically described as', options: ['cyclohexanoperhydronaphthalene', 'cyclopentanoperhydrophenanthrene', 'perhydroazulene', 'tetrahydroisoquinoline'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The steroid skeleton is three fused six membered rings and one five membered ring, that is a cyclopentane ring fused to a fully saturated phenanthrene.', source },
  { id: 'gpat-2026-pharmacy-02-055', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: nucleic acid bases', difficulty: 'easy', question: 'Which of the following is a purine base?', options: ['Cytosine', 'Thymine', 'Adenine', 'Uracil'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Adenine and guanine are purines, built on a fused imidazole and pyrimidine ring system. Cytosine, thymine and uracil are single ring pyrimidines.', source },
  { id: 'gpat-2026-pharmacy-02-056', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: nucleic acid bases', difficulty: 'easy', question: 'Which of the following is a pyrimidine base?', options: ['Adenine', 'Guanine', 'Hypoxanthine', 'Cytosine'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Cytosine, thymine and uracil are pyrimidines. Adenine, guanine and hypoxanthine are purines.', source },
  { id: 'gpat-2026-pharmacy-02-057', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: drug stability', difficulty: 'medium', question: 'Hydrolysis of an ester drug in aqueous solution is commonly accelerated by', options: ['both hydrogen ions and hydroxyl ions', 'hydrogen ions only', 'hydroxyl ions only', 'neither, since the reaction is not pH dependent'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Ester hydrolysis usually shows specific acid and specific base catalysis, giving a V shaped log rate against pH profile with a minimum at the pH of maximum stability.', source },
  { id: 'gpat-2026-pharmacy-02-058', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: drug stability', difficulty: 'medium', question: 'Racemisation of an optically active drug in solution results in', options: ['an increase in optical rotation', 'loss of optical rotation and often loss of potency', 'conversion to a structural isomer with a different molecular formula', 'formation of a polymeric degradation product'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Racemisation converts a single enantiomer into an equimolar mixture of both, which is optically inactive. If only one enantiomer is active, the potency falls by about half.', source },
  { id: 'gpat-2026-pharmacy-02-059', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: complexation', difficulty: 'medium', question: 'Forming an inclusion complex of a drug with a cyclodextrin is used chiefly to', options: ['reduce the melting point of the drug', 'increase the molecular weight for slower renal clearance', 'improve aqueous solubility and stability', 'convert the drug into a prodrug'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'A cyclodextrin has a hydrophilic exterior and a lipophilic cavity, so it can host a poorly soluble drug and carry it into solution while also shielding it from oxidation and hydrolysis.', source },
  { id: 'gpat-2026-pharmacy-02-060', section: 'Pharmacy', topic: 'Pharmaceutical Chemistry: ionisation', difficulty: 'easy', question: 'The pKa of a weak acid is the pH at which', options: ['the acid is completely ionised', 'the acid is completely un-ionised', 'the solution has no buffering capacity', 'the acid is exactly half ionised'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'By the Henderson Hasselbalch equation, when the concentrations of the acid and its conjugate base are equal the logarithmic term vanishes and the pH equals the pKa.', source },
  { id: 'gpat-2026-pharmacy-02-061', section: 'Pharmacy', topic: 'Pharmacology: receptors', difficulty: 'medium', question: 'Nicotinic acetylcholine receptors are', options: ['ligand gated ion channels', 'G protein coupled receptors', 'nuclear receptors', 'enzyme linked receptors'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The nicotinic receptor is a pentameric channel that opens to cations within milliseconds of binding acetylcholine. The muscarinic receptors, by contrast, are G protein coupled.', source },
  { id: 'gpat-2026-pharmacy-02-062', section: 'Pharmacy', topic: 'Pharmacology: receptors', difficulty: 'medium', question: 'Muscarinic acetylcholine receptors belong to which superfamily?', options: ['Ligand gated ion channels', 'G protein coupled receptors', 'Receptor tyrosine kinases', 'Cytosolic steroid receptors'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'All five muscarinic subtypes are seven transmembrane G protein coupled receptors, which is why their responses develop over seconds rather than milliseconds.', source },
  { id: 'gpat-2026-pharmacy-02-063', section: 'Pharmacy', topic: 'Pharmacology: cholinergic drugs', difficulty: 'easy', question: 'Atropine acts as', options: ['an agonist at muscarinic receptors', 'an antagonist at nicotinic receptors', 'a competitive antagonist at muscarinic receptors', 'an inhibitor of acetylcholinesterase'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Atropine blocks muscarinic receptors competitively, producing dry mouth, mydriasis, tachycardia and reduced secretions.', source },
  { id: 'gpat-2026-pharmacy-02-064', section: 'Pharmacy', topic: 'Pharmacology: adrenergic drugs', difficulty: 'easy', question: 'Propranolol is best classified as', options: ['a selective beta-1 antagonist', 'a selective beta-2 agonist', 'an alpha-1 antagonist', 'a non-selective beta adrenergic antagonist'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Propranolol blocks beta-1 and beta-2 receptors about equally, which is why bronchospasm is a concern in asthmatic patients. Atenolol and metoprolol are the beta-1 selective agents.', source },
  { id: 'gpat-2026-pharmacy-02-065', section: 'Pharmacy', topic: 'Pharmacology: adrenergic drugs', difficulty: 'easy', question: 'Salbutamol produces bronchodilation by acting as', options: ['a beta-2 adrenergic agonist', 'a beta-1 adrenergic agonist', 'a muscarinic antagonist', 'a leukotriene receptor antagonist'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Salbutamol selectively stimulates beta-2 receptors on airway smooth muscle, raising cyclic AMP and relaxing the muscle.', source },
  { id: 'gpat-2026-pharmacy-02-066', section: 'Pharmacy', topic: 'Pharmacology: NSAIDs', difficulty: 'medium', question: 'Aspirin differs from most other non-steroidal anti-inflammatory drugs in that it inhibits cyclooxygenase', options: ['reversibly and competitively', 'irreversibly, by acetylating a serine residue', 'only in the central nervous system', 'only the COX-2 isoform'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Aspirin acetylates serine 530 of COX-1 and serine 516 of COX-2. Because platelets cannot synthesise new enzyme, a single dose suppresses platelet thromboxane for the life of the platelet.', source },
  { id: 'gpat-2026-pharmacy-02-067', section: 'Pharmacy', topic: 'Pharmacology: gastrointestinal drugs', difficulty: 'easy', question: 'Omeprazole reduces gastric acid secretion by inhibiting', options: ['histamine H2 receptors', 'muscarinic M1 receptors', 'the H+/K+ ATPase of the parietal cell', 'gastrin receptors'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Omeprazole is a prodrug activated in the acidic canaliculus, where it binds covalently to the proton pump, the final common step of acid secretion.', source },
  { id: 'gpat-2026-pharmacy-02-068', section: 'Pharmacy', topic: 'Pharmacology: gastrointestinal drugs', difficulty: 'easy', question: 'Ranitidine reduces gastric acid secretion by blocking', options: ['histamine H1 receptors', 'the gastric proton pump', 'prostaglandin EP3 receptors', 'histamine H2 receptors'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'H2 receptor antagonists block the histamine driven component of acid secretion on the parietal cell, and are less complete inhibitors than the proton pump inhibitors.', source },
  { id: 'gpat-2026-pharmacy-02-069', section: 'Pharmacy', topic: 'Pharmacology: anticoagulants', difficulty: 'medium', question: 'Warfarin exerts its anticoagulant effect by inhibiting', options: ['vitamin K epoxide reductase', 'antithrombin III', 'factor Xa directly', 'platelet cyclooxygenase'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'By blocking the regeneration of reduced vitamin K, warfarin prevents gamma carboxylation of factors II, VII, IX and X, so the effect appears only as existing factors are cleared.', source },
  { id: 'gpat-2026-pharmacy-02-070', section: 'Pharmacy', topic: 'Pharmacology: anticoagulants', difficulty: 'medium', question: 'Heparin produces its anticoagulant effect chiefly by', options: ['inhibiting vitamin K epoxide reductase', 'potentiating antithrombin III', 'chelating calcium in the plasma', 'blocking platelet ADP receptors'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Heparin binds antithrombin III and accelerates its inactivation of thrombin and factor Xa by several thousandfold, which is why its effect is immediate.', source },
  { id: 'gpat-2026-pharmacy-02-071', section: 'Pharmacy', topic: 'Pharmacology: cardiac drugs', difficulty: 'medium', question: 'Digoxin increases the force of cardiac contraction by inhibiting', options: ['the L type calcium channel', 'beta-1 adrenergic receptors', 'the sodium potassium ATPase', 'phosphodiesterase type 3'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Inhibiting the sodium pump raises intracellular sodium, which reduces calcium extrusion through the sodium calcium exchanger and so raises intracellular calcium.', source },
  { id: 'gpat-2026-pharmacy-02-072', section: 'Pharmacy', topic: 'Pharmacology: diuretics', difficulty: 'medium', question: 'Furosemide acts on which part of the nephron?', options: ['The proximal convoluted tubule', 'The distal convoluted tubule', 'The collecting duct', 'The thick ascending limb of the loop of Henle'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Furosemide inhibits the sodium potassium two chloride cotransporter in the thick ascending limb, abolishing the medullary concentration gradient and producing a large diuresis.', source },
  { id: 'gpat-2026-pharmacy-02-073', section: 'Pharmacy', topic: 'Pharmacology: diuretics', difficulty: 'medium', question: 'Thiazide diuretics inhibit sodium reabsorption in', options: ['the distal convoluted tubule', 'the thick ascending limb', 'the proximal convoluted tubule', 'the collecting duct'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Thiazides block the sodium chloride cotransporter of the early distal tubule, a segment that reabsorbs a smaller fraction of the filtered sodium than the loop, which is why they are less powerful than loop diuretics.', source },
  { id: 'gpat-2026-pharmacy-02-074', section: 'Pharmacy', topic: 'Pharmacology: diuretics', difficulty: 'easy', question: 'Spironolactone is best described as', options: ['a carbonic anhydrase inhibitor', 'an aldosterone receptor antagonist', 'an osmotic diuretic', 'a sodium channel blocker in the proximal tubule'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Spironolactone competes with aldosterone at the mineralocorticoid receptor in the collecting duct, so it spares potassium while producing a modest diuresis.', source },
  { id: 'gpat-2026-pharmacy-02-075', section: 'Pharmacy', topic: 'Pharmacology: antihypertensives', difficulty: 'easy', question: 'Angiotensin converting enzyme inhibitors lower blood pressure principally by reducing the formation of', options: ['renin', 'aldosterone synthase', 'angiotensin II', 'bradykinin'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'They block the conversion of angiotensin I to angiotensin II, reducing vasoconstriction and aldosterone release. The same enzyme degrades bradykinin, whose accumulation explains the dry cough.', source },
  { id: 'gpat-2026-pharmacy-02-076', section: 'Pharmacy', topic: 'Pharmacology: lipid lowering drugs', difficulty: 'easy', question: 'Statins lower plasma cholesterol by inhibiting', options: ['lipoprotein lipase', 'cholesterol ester transfer protein', 'pancreatic lipase', 'HMG-CoA reductase'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'HMG-CoA reductase catalyses the rate limiting step of hepatic cholesterol synthesis. Inhibiting it upregulates LDL receptors and clears LDL from the plasma.', source },
  { id: 'gpat-2026-pharmacy-02-077', section: 'Pharmacy', topic: 'Pharmacology: antidiabetic drugs', difficulty: 'medium', question: 'The principal action of metformin is to', options: ['reduce hepatic glucose production', 'stimulate insulin release from beta cells', 'inhibit intestinal alpha glucosidase', 'increase renal glucose excretion'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Metformin lowers hepatic gluconeogenesis and improves peripheral insulin sensitivity without stimulating insulin secretion, which is why it does not by itself cause hypoglycaemia.', source },
  { id: 'gpat-2026-pharmacy-02-078', section: 'Pharmacy', topic: 'Pharmacology: antidiabetic drugs', difficulty: 'medium', question: 'Sulphonylureas lower blood glucose by', options: ['inhibiting hepatic gluconeogenesis', 'closing ATP sensitive potassium channels in pancreatic beta cells', 'blocking the sodium glucose cotransporter 2', 'activating peroxisome proliferator activated receptor gamma'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Closing the potassium channel depolarises the beta cell, opens voltage gated calcium channels and triggers insulin release, so the class requires functioning beta cells.', source },
  { id: 'gpat-2026-pharmacy-02-079', section: 'Pharmacy', topic: 'Pharmacology: antibacterials', difficulty: 'easy', question: 'Penicillins kill bacteria by', options: ['binding the 30S ribosomal subunit', 'inhibiting DNA gyrase', 'inhibiting cross linking of the peptidoglycan cell wall', 'disrupting the cytoplasmic membrane'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Penicillins acylate the transpeptidase enzymes, also called penicillin binding proteins, that cross link peptidoglycan strands, so the wall weakens and the cell lyses.', source },
  { id: 'gpat-2026-pharmacy-02-080', section: 'Pharmacy', topic: 'Pharmacology: antibacterials', difficulty: 'medium', question: 'Aminoglycoside antibiotics act on', options: ['the 50S ribosomal subunit', 'bacterial RNA polymerase', 'dihydrofolate reductase', 'the 30S ribosomal subunit'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Aminoglycosides bind the 30S subunit, causing misreading of messenger RNA and blocking translocation, which makes them bactericidal.', source },
  { id: 'gpat-2026-pharmacy-02-081', section: 'Pharmacy', topic: 'Pharmacology: antibacterials', difficulty: 'medium', question: 'Macrolide antibiotics such as erythromycin act on', options: ['the 50S ribosomal subunit', 'the 30S ribosomal subunit', 'the bacterial cell wall', 'bacterial topoisomerase IV'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Macrolides bind the 23S ribosomal RNA of the 50S subunit and block translocation of the growing peptide chain.', source },
  { id: 'gpat-2026-pharmacy-02-082', section: 'Pharmacy', topic: 'Pharmacology: antibacterials', difficulty: 'medium', question: 'Absorption of tetracycline from the gut is markedly reduced by', options: ['a high protein meal', 'milk and antacids containing calcium, magnesium or aluminium', 'an acidic fruit juice', 'concurrent vitamin C'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Tetracyclines chelate divalent and trivalent cations to form insoluble complexes, so dairy products and cation containing antacids should be separated from the dose.', source },
  { id: 'gpat-2026-pharmacy-02-083', section: 'Pharmacy', topic: 'Pharmacology: antitubercular drugs', difficulty: 'medium', question: 'Rifampicin acts by inhibiting', options: ['mycolic acid synthesis', 'arabinosyl transferase', 'bacterial DNA dependent RNA polymerase', 'the 30S ribosomal subunit'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Rifampicin binds the beta subunit of bacterial RNA polymerase and blocks the initiation of transcription. Isoniazid inhibits mycolic acid synthesis and ethambutol arabinosyl transferase.', source },
  { id: 'gpat-2026-pharmacy-02-084', section: 'Pharmacy', topic: 'Pharmacology: pharmacokinetics', difficulty: 'easy', question: 'First pass metabolism refers to', options: ['metabolism of the first dose only in a course of treatment', 'the fastest of several parallel metabolic pathways', 'conversion of a drug to its first identified metabolite', 'metabolism of a drug before it reaches the systemic circulation'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'An orally absorbed drug passes through the gut wall and the liver before entering the general circulation, and the loss there can greatly reduce oral bioavailability.', source },
  { id: 'gpat-2026-pharmacy-02-085', section: 'Pharmacy', topic: 'Pharmacology: pharmacokinetics', difficulty: 'medium', question: 'The apparent volume of distribution of a drug relates', options: ['the amount of drug in the body to its plasma concentration', 'the dose administered to the amount excreted unchanged', 'the clearance to the elimination half life alone', 'the free fraction to the bound fraction in plasma'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'It is the proportionality constant between the total amount in the body and the measured plasma concentration, and a large value indicates extensive distribution into tissues.', source },
  { id: 'gpat-2026-pharmacy-02-086', section: 'Pharmacy', topic: 'Pharmaceutical Analysis: spectroscopy', difficulty: 'easy', question: 'The Beer Lambert law states that absorbance is directly proportional to', options: ['concentration and the square of the path length', 'concentration and path length', 'transmittance and path length', 'wavelength and concentration'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Absorbance equals molar absorptivity times path length times concentration, so a plot of absorbance against concentration at fixed path length is a straight line through the origin.', source },
  { id: 'gpat-2026-pharmacy-02-087', section: 'Pharmacy', topic: 'Pharmaceutical Analysis: spectroscopy', difficulty: 'medium', question: 'In ultraviolet spectroscopy, a chromophore is', options: ['a group that shifts absorption to a longer wavelength without absorbing itself', 'the solvent used to dissolve the sample', 'the functional group responsible for the absorption', 'the reference cell in a double beam instrument'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'A chromophore such as a carbonyl or an aromatic ring absorbs ultraviolet radiation. An auxochrome does not absorb appreciably itself but shifts and intensifies the chromophore\'s band.', source },
  { id: 'gpat-2026-pharmacy-02-088', section: 'Pharmacy', topic: 'Pharmaceutical Analysis: chromatography', difficulty: 'medium', question: 'In reversed phase high performance liquid chromatography', options: ['the stationary phase is polar and the mobile phase non-polar', 'both phases are non-polar', 'the stationary phase is a gas', 'the stationary phase is non-polar and the mobile phase polar'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'A typical reversed phase column is octadecylsilane bonded silica run with water and acetonitrile or methanol, so the more lipophilic analytes are retained longer.', source },
  { id: 'gpat-2026-pharmacy-02-089', section: 'Pharmacy', topic: 'Pharmaceutical Analysis: chromatography', difficulty: 'easy', question: 'In thin layer chromatography the retardation factor Rf is calculated as', options: ['the distance travelled by the solute divided by the distance travelled by the solvent front', 'the distance travelled by the solvent front divided by the distance travelled by the solute', 'the spot area divided by the plate area', 'the retention time divided by the run time'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Rf therefore always lies between 0 and 1 for a spot that has moved but not reached the front, and it is characteristic of a compound in a given system.', source },
  { id: 'gpat-2026-pharmacy-02-090', section: 'Pharmacy', topic: 'Pharmaceutical Analysis: chromatography', difficulty: 'medium', question: 'The number of theoretical plates of a chromatographic column is a measure of', options: ['column selectivity', 'column efficiency', 'detector sensitivity', 'sample capacity'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'A larger plate number means narrower peaks for a given retention time. Selectivity is described by the separation factor and capacity by the loading limit.', source },
  { id: 'gpat-2026-pharmacy-02-091', section: 'Pharmacy', topic: 'Pharmaceutical Analysis: chromatography', difficulty: 'medium', question: 'The flame ionisation detector used in gas chromatography responds to', options: ['all compounds including permanent gases', 'only halogen containing compounds', 'organic compounds that produce ions on combustion', 'only compounds that absorb ultraviolet light'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The flame ionisation detector burns the eluate in a hydrogen and air flame and measures the current from the carbon ions formed, so it is nearly blind to water, nitrogen and carbon dioxide.', source },
  { id: 'gpat-2026-pharmacy-02-092', section: 'Pharmacy', topic: 'Pharmaceutical Analysis: titrimetry', difficulty: 'easy', question: 'Karl Fischer titration is used to determine', options: ['total acidity', 'hydroxyl value', 'residual solvent other than water', 'water content'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The Karl Fischer reagent consumes water stoichiometrically in a reaction involving iodine, sulphur dioxide and a base, and is the compendial method for moisture.', source },
  { id: 'gpat-2026-pharmacy-02-093', section: 'Pharmacy', topic: 'Pharmaceutical Analysis: titrimetry', difficulty: 'medium', question: 'Non-aqueous titration with perchloric acid in glacial acetic acid is used to assay', options: ['weak bases', 'strong acids', 'neutral esters', 'inorganic salts of strong acids and strong bases'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Glacial acetic acid is a protogenic solvent that enhances the basicity of a weak base, allowing a sharp end point that water would level out.', source },
  { id: 'gpat-2026-pharmacy-02-094', section: 'Pharmacy', topic: 'Pharmaceutical Analysis: electroanalysis', difficulty: 'medium', question: 'In potentiometric pH measurement, the glass electrode serves as', options: ['the reference electrode', 'the indicator electrode', 'the counter electrode', 'the salt bridge'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The glass membrane develops a potential that varies with hydrogen ion activity, and it is measured against a reference electrode of fixed potential, usually silver silver chloride or calomel.', source },
  { id: 'gpat-2026-pharmacy-02-095', section: 'Pharmacy', topic: 'Pharmaceutical Analysis: mass spectrometry', difficulty: 'medium', question: 'In a mass spectrum, the base peak is', options: ['the peak of highest mass to charge ratio', 'the peak corresponding to the intact molecule', 'the most intense peak in the spectrum', 'the peak produced by the carrier gas'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The base peak is assigned a relative intensity of 100 per cent and all other peaks are scaled to it. The peak of the intact molecule is the molecular ion peak, which may be weak or absent.', source },
  { id: 'gpat-2026-pharmacy-02-096', section: 'Pharmacy', topic: 'Pharmaceutical Analysis: NMR', difficulty: 'medium', question: 'In proton nuclear magnetic resonance spectroscopy, tetramethylsilane is used as', options: ['the deuterated solvent', 'a relaxation agent', 'a shift reagent for lanthanide complexes', 'the internal reference defined as zero on the delta scale'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Tetramethylsilane has twelve equivalent, strongly shielded protons giving a single sharp signal, is chemically inert and is volatile enough to be removed after the measurement.', source },
  { id: 'gpat-2026-pharmacy-02-097', section: 'Pharmacy', topic: 'Pharmaceutical Analysis: thermal methods', difficulty: 'hard', question: 'Which technique measures the heat absorbed or released by a sample against a reference as the temperature is changed?', options: ['Differential scanning calorimetry', 'Thermogravimetric analysis', 'X-ray powder diffraction', 'Dynamic light scattering'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Differential scanning calorimetry records heat flow and so detects melting, crystallisation, glass transitions and polymorphic changes. Thermogravimetric analysis records mass change instead.', source },
  { id: 'gpat-2026-pharmacy-02-098', section: 'Pharmacy', topic: 'Pharmacognosy: glycosides', difficulty: 'easy', question: 'Digitalis leaf is a source of', options: ['anthraquinone glycosides', 'cardiac glycosides', 'cyanogenetic glycosides', 'saponin glycosides'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Digitalis purpurea and Digitalis lanata yield digitoxin, digoxin and related cardenolides, which inhibit the sodium pump of cardiac muscle.', source },
  { id: 'gpat-2026-pharmacy-02-099', section: 'Pharmacy', topic: 'Pharmacognosy: alkaloids', difficulty: 'medium', question: 'The principal antihypertensive alkaloid of Rauwolfia serpentina is', options: ['morphine', 'ephedrine', 'reserpine', 'colchicine'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Reserpine depletes catecholamine stores by blocking the vesicular monoamine transporter. Rauwolfia root also contains ajmaline and serpentine.', source },
  { id: 'gpat-2026-pharmacy-02-100', section: 'Pharmacy', topic: 'Pharmacognosy: alkaloids', difficulty: 'easy', question: 'Opium is obtained from', options: ['the dried root of Papaver somniferum', 'the seeds of Papaver somniferum', 'the whole flowering herb of Papaver rhoeas', 'the dried latex of the unripe capsules of Papaver somniferum'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The unripe capsule is incised and the exuding latex is dried. Opium contains morphine, codeine, thebaine, papaverine and noscapine.', source },
  { id: 'gpat-2026-pharmacy-02-101', section: 'Pharmacy', topic: 'Pharmacognosy: alkaloids', difficulty: 'easy', question: 'Quinine is obtained from', options: ['the bark of Cinchona species', 'the leaf of Cinchona species', 'the root of Artemisia annua', 'the seed of Strychnos nux-vomica'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Cinchona bark contains quinine, quinidine, cinchonine and cinchonidine. Artemisia annua yields artemisinin and Strychnos nux-vomica yields strychnine.', source },
  { id: 'gpat-2026-pharmacy-02-102', section: 'Pharmacy', topic: 'Pharmacognosy: glycosides', difficulty: 'medium', question: 'The purgative action of senna is attributed to', options: ['cardiac glycosides', 'anthraquinone glycosides', 'volatile oil', 'tannins'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Sennosides A and B are hydrolysed by colonic bacteria to rhein anthrone, which stimulates peristalsis and reduces water absorption.', source },
  { id: 'gpat-2026-pharmacy-02-103', section: 'Pharmacy', topic: 'Pharmacognosy: alkaloids', difficulty: 'easy', question: 'Which alkaloid is obtained from Atropa belladonna?', options: ['Reserpine', 'Quinine', 'Atropine', 'Emetine'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Belladonna leaf and root yield the tropane alkaloids hyoscyamine and atropine, together with small amounts of hyoscine.', source },
  { id: 'gpat-2026-pharmacy-02-104', section: 'Pharmacy', topic: 'Pharmacognosy: carbohydrates', difficulty: 'medium', question: 'Agar is obtained from', options: ['brown algae', 'a fungal mycelium', 'the seed endosperm of a legume', 'red algae'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Agar comes from Gelidium and Gracilaria species of red algae. Alginate comes from brown algae and guar gum from the seed endosperm of Cyamopsis tetragonoloba.', source },
  { id: 'gpat-2026-pharmacy-02-105', section: 'Pharmacy', topic: 'Pharmacognosy: terpenoids', difficulty: 'medium', question: 'Paclitaxel, a diterpene used in cancer chemotherapy, is obtained from', options: ['Taxus species', 'Catharanthus roseus', 'Podophyllum species', 'Camptotheca acuminata'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Paclitaxel was first isolated from the bark of Taxus brevifolia. Catharanthus roseus yields vincristine and vinblastine, and Camptotheca acuminata yields camptothecin.', source },
  { id: 'gpat-2026-pharmacy-02-106', section: 'Pharmacy', topic: 'Pharmacognosy: chemical tests', difficulty: 'medium', question: 'Borntrager\'s test is used to detect', options: ['cardiac glycosides', 'anthraquinone glycosides', 'alkaloids', 'tannins'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'On treatment with alkali after oxidation the free anthraquinones give a pink to red colour in the ammoniacal layer, which is the positive Borntrager reaction.', source },
  { id: 'gpat-2026-pharmacy-02-107', section: 'Pharmacy', topic: 'Pharmacognosy: chemical tests', difficulty: 'easy', question: 'Dragendorff\'s reagent is used to detect', options: ['glycosides', 'sterols', 'alkaloids', 'proteins'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Dragendorff\'s reagent, potassium bismuth iodide, gives an orange to reddish brown precipitate with alkaloids and is a standard screening test.', source },
  { id: 'gpat-2026-pharmacy-02-108', section: 'Pharmacy', topic: 'Biochemistry and Human Physiology: glycolysis', difficulty: 'medium', question: 'The rate limiting enzyme of glycolysis is', options: ['hexokinase', 'pyruvate kinase', 'aldolase', 'phosphofructokinase-1'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Phosphofructokinase-1 catalyses the committed step and is allosterically inhibited by ATP and citrate and activated by AMP and fructose 2,6-bisphosphate.', source },
  { id: 'gpat-2026-pharmacy-02-109', section: 'Pharmacy', topic: 'Biochemistry and Human Physiology: metabolism', difficulty: 'easy', question: 'In eukaryotic cells the citric acid cycle takes place in', options: ['the mitochondrial matrix', 'the cytosol', 'the endoplasmic reticulum', 'the nucleus'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The enzymes of the cycle are in the matrix, with succinate dehydrogenase embedded in the inner mitochondrial membrane. Glycolysis, by contrast, is cytosolic.', source },
  { id: 'gpat-2026-pharmacy-02-110', section: 'Pharmacy', topic: 'Biochemistry and Human Physiology: acid base balance', difficulty: 'easy', question: 'The normal pH range of arterial blood is', options: ['6.8 to 7.0', '7.35 to 7.45', '7.0 to 7.2', '7.6 to 7.8'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Arterial pH is held in this narrow band mainly by the bicarbonate carbonic acid buffer together with respiratory and renal compensation.', source },
  { id: 'gpat-2026-pharmacy-02-111', section: 'Pharmacy', topic: 'Biochemistry and Human Physiology: endocrinology', difficulty: 'easy', question: 'Insulin is secreted by', options: ['the alpha cells of the islets of Langerhans', 'the acinar cells of the pancreas', 'the beta cells of the islets of Langerhans', 'the chief cells of the parathyroid'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Beta cells make up the majority of the islet and secrete insulin. Alpha cells secrete glucagon and delta cells somatostatin.', source },
  { id: 'gpat-2026-pharmacy-02-112', section: 'Pharmacy', topic: 'Biochemistry and Human Physiology: renal physiology', difficulty: 'easy', question: 'The structural and functional unit of the kidney is', options: ['the glomerulus alone', 'the renal pyramid', 'the collecting duct', 'the nephron'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Each nephron consists of a renal corpuscle and its tubule. The glomerulus is only part of the corpuscle, and the collecting duct is shared by many nephrons.', source },
  { id: 'gpat-2026-pharmacy-02-113', section: 'Pharmacy', topic: 'Biochemistry and Human Physiology: blood', difficulty: 'medium', question: 'Haemoglobin carries oxygen by binding it reversibly to', options: ['the ferrous iron of the haem group', 'the globin polypeptide chain', 'a bound molecule of 2,3-bisphosphoglycerate', 'the carbonate ion in the plasma'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Each of the four haem groups binds one oxygen molecule at its ferrous iron. Oxidation of that iron to the ferric state gives methaemoglobin, which cannot carry oxygen.', source },
  { id: 'gpat-2026-pharmacy-02-114', section: 'Pharmacy', topic: 'Biochemistry and Human Physiology: vitamins', difficulty: 'easy', question: 'Deficiency of which vitamin causes scurvy?', options: ['Vitamin A', 'Vitamin C', 'Vitamin D', 'Vitamin K'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Ascorbic acid is required for the hydroxylation of proline and lysine in collagen synthesis, so its deficiency produces bleeding gums, poor wound healing and perifollicular haemorrhage.', source },
  { id: 'gpat-2026-pharmacy-02-115', section: 'Pharmacy', topic: 'Biochemistry and Human Physiology: cardiovascular physiology', difficulty: 'easy', question: 'The normal resting heart rate of a healthy adult is', options: ['30 to 50 beats per minute', '110 to 140 beats per minute', '60 to 100 beats per minute', '150 to 180 beats per minute'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Rates below 60 are described as bradycardia and rates above 100 as tachycardia, although trained athletes may normally be below 60.', source },
  { id: 'gpat-2026-pharmacy-02-116', section: 'Pharmacy', topic: 'Pharmaceutical Microbiology and Biotechnology: staining', difficulty: 'medium', question: 'Gram positive bacteria retain the crystal violet iodine complex because they have', options: ['an outer membrane rich in lipopolysaccharide', 'a waxy mycolic acid coat', 'no cell wall at all', 'a thick peptidoglycan layer'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The thick, highly cross linked peptidoglycan traps the dye complex when the decolouriser is applied. Gram negative organisms have a thin peptidoglycan layer beneath an outer membrane and lose the stain.', source },
  { id: 'gpat-2026-pharmacy-02-117', section: 'Pharmacy', topic: 'Pharmaceutical Microbiology and Biotechnology: sterilisation', difficulty: 'easy', question: 'Which method is appropriate for sterilising a heat labile solution?', options: ['Filtration through a 0.22 micrometre membrane', 'Autoclaving at 121 degrees Celsius', 'Dry heat at 160 degrees Celsius', 'Flaming'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Membrane filtration removes bacteria physically without heating the product. The filtrate must be collected and filled under aseptic conditions, since the process does not inactivate anything left downstream.', source },
  { id: 'gpat-2026-pharmacy-02-118', section: 'Pharmacy', topic: 'Pharmaceutical Microbiology and Biotechnology: recombinant products', difficulty: 'easy', question: 'Recombinant human insulin is produced commercially in', options: ['cultured human pancreatic tissue', 'genetically engineered Escherichia coli or yeast', 'the pancreas of cattle and pigs', 'a chemical synthesis from amino acids alone'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The human proinsulin gene is expressed in a microbial host and the product is then processed and purified, which removes the immunogenicity and supply limits of animal insulin.', source },
  { id: 'gpat-2026-pharmacy-02-119', section: 'Pharmacy', topic: 'Pharmaceutical Microbiology and Biotechnology: antibodies', difficulty: 'medium', question: 'Monoclonal antibodies of uniform specificity are produced by', options: ['immunising an animal and collecting its serum', 'precipitating gamma globulin from pooled plasma', 'hybridoma technology', 'enzymatic digestion of polyclonal antibody'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Fusing an antibody producing B lymphocyte with an immortal myeloma cell gives a hybridoma that both survives in culture and secretes a single antibody species.', source },
  { id: 'gpat-2026-pharmacy-02-120', section: 'Pharmacy', topic: 'Pharmaceutical Microbiology and Biotechnology: sterilisation kinetics', difficulty: 'hard', question: 'The D value in sterilisation is the time required at a stated temperature to', options: ['reduce the microbial population by 50 per cent', 'achieve complete sterility of the load', 'raise the load temperature to the set point', 'reduce the microbial population by 90 per cent'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The D value is one log reduction, so a 12 log reduction of a resistant spore requires twelve D values. The Z value, by contrast, is the temperature change that alters D tenfold.', source },
  { id: 'gpat-2026-pharmacy-02-121', section: 'Pharmacy', topic: 'Pharmaceutical Jurisprudence and Pharmacy Practice: drug schedules', difficulty: 'medium', question: 'Schedule H of the Drugs and Cosmetics Rules lists', options: ['drugs that may be sold only on the prescription of a registered medical practitioner', 'standards for the good manufacturing practice of premises and equipment', 'the list of drugs prohibited from manufacture in India', 'the labelling requirements for cosmetics'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Schedule H drugs carry the caution that they are to be sold by retail only against a prescription. Schedule M sets manufacturing standards and Schedule X covers the more tightly controlled psychotropic substances.', source },
  { id: 'gpat-2026-pharmacy-02-122', section: 'Pharmacy', topic: 'Pharmaceutical Jurisprudence and Pharmacy Practice: drug schedules', difficulty: 'medium', question: 'Schedule M of the Drugs and Cosmetics Rules deals with', options: ['drugs sold only against a prescription', 'good manufacturing practices and requirements of premises, plant and equipment', 'the list of permitted colouring agents', 'the fees payable for a manufacturing licence'], correctIndex: 1, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Schedule M prescribes the general and specific requirements for factory premises, equipment, quality control and documentation for manufacturers of pharmaceutical products.', source },
  { id: 'gpat-2026-pharmacy-02-123', section: 'Pharmacy', topic: 'Pharmaceutical Jurisprudence and Pharmacy Practice: pharmacovigilance', difficulty: 'easy', question: 'Pharmacovigilance is best defined as', options: ['the study of the movement of drugs within the body', 'the analysis of the cost effectiveness of medicines', 'the science of detection, assessment, understanding and prevention of adverse effects of medicines', 'the inspection of manufacturing premises for compliance'], correctIndex: 2, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'Pharmacovigilance covers spontaneous reporting, signal detection and risk management for medicines already on the market, in contrast to pharmacokinetics, pharmacoeconomics and regulatory inspection.', source },
  { id: 'gpat-2026-pharmacy-02-124', section: 'Pharmacy', topic: 'Pharmaceutical Jurisprudence and Pharmacy Practice: prescription handling', difficulty: 'easy', question: 'In a prescription, the abbreviation b.d. or b.i.d. directs that the medicine be taken', options: ['once a day', 'three times a day', 'at bedtime only', 'twice a day'], correctIndex: 3, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The abbreviation is from the Latin bis in die. Once daily is o.d., three times daily is t.d.s. or t.i.d., and at bedtime is h.s.', source },
  { id: 'gpat-2026-pharmacy-02-125', section: 'Pharmacy', topic: 'Pharmaceutical Jurisprudence and Pharmacy Practice: pharmacy law', difficulty: 'medium', question: 'The Pharmacy Act of 1948 provided for the constitution of', options: ['the Pharmacy Council of India', 'the Central Drugs Standard Control Organisation', 'the Indian Pharmacopoeia Commission', 'the National Pharmaceutical Pricing Authority'], correctIndex: 0, answerType: 'mcq', marks: 4, negativeMarking: 1, explanation: 'The Act established the Pharmacy Council of India to prescribe the minimum education standard for registration as a pharmacist, and State Pharmacy Councils to maintain the registers.', source },
];
